INSERT INTO public.faqs VALUES ('cmsoe3mrj0000q23jnzlrwtse', 'What does uPVC stand for?', 'uPVC stands for Unplasticized Polyvinyl Chloride. It is a rigid, durable form of PVC that has not had any plasticizers added to it, making it stronger and more suitable for construction and piping.', 1, true, '2026-08-11 08:19:47.839', '2026-08-11 08:19:47.839');
INSERT INTO public.faqs VALUES ('cmsoe3mrl0001q23je7z0v38s', 'Why should I choose uPVC pipes over metal pipes?', 'uPVC pipes are lightweight, corrosion-resistant, and do not rust or scale over time like metal pipes. They are also much easier and cheaper to install, and provide a longer lifespan.', 2, true, '2026-08-11 08:19:47.841', '2026-08-11 08:19:47.841');
INSERT INTO public.faqs VALUES ('cmsoe3mrm0002q23jbupypkms', 'Are Talukder uPVC pipes safe for drinking water?', 'Yes, absolutely. Our pipes are manufactured using 100% virgin food-grade material and are completely lead-free, ensuring the water remains safe, clean, and uncontaminated.', 3, true, '2026-08-11 08:19:47.842', '2026-08-11 08:19:47.842');
INSERT INTO public.faqs VALUES ('cmsoe3mrn0003q23j9s24odvp', 'What is the standard lifespan of a uPVC pipe?', 'When properly installed, high-quality uPVC pipes like ours can easily last over 50 years. They are highly resistant to chemical erosion, weathering, and underground pressure.', 4, true, '2026-08-11 08:19:47.844', '2026-08-11 08:19:47.844');
INSERT INTO public.faqs VALUES ('cmsoe3mrp0004q23jg621bbck', 'Do your products comply with international standards?', 'Yes, all our uPVC pipes and fittings are rigorously tested and manufactured in strict compliance with the BS-3505 British Standard.', 5, true, '2026-08-11 08:19:47.845', '2026-08-11 08:19:47.845');
INSERT INTO public.faqs VALUES ('cmsoe3mrq0005q23j04hxfkeg', 'What types of pipes do you manufacture?', 'We manufacture a comprehensive range of pipes including Pressure Pipes, SWR Pipes, Thread/Casing Pipes, Filter Pipes, and Ribbed Pipes for various applications like plumbing, agriculture, and sanitation.', 6, true, '2026-08-11 08:19:47.847', '2026-08-11 08:19:47.847');
INSERT INTO public.faqs VALUES ('cmsoe3mrr0006q23jfsg0skxu', 'Do you use recycled plastics in your manufacturing?', 'No, we never use recycled plastics. We strictly use 100% virgin raw materials to guarantee the structural integrity and longevity of our products.', 7, true, '2026-08-11 08:19:47.848', '2026-08-11 08:19:47.848');
INSERT INTO public.faqs VALUES ('cmsoe3mrs0007q23jg7q3z2bq', 'What is an SWR pipe used for?', 'SWR stands for Soil, Waste, and Rain. SWR uPVC pipes are specifically designed for efficient removal of wastewater, sewage, and rainwater in residential and commercial buildings.', 8, true, '2026-08-11 08:19:47.849', '2026-08-11 08:19:47.849');
INSERT INTO public.faqs VALUES ('cmsoe3mrt0008q23jbsfias65', 'Can uPVC pipes withstand high temperatures?', 'uPVC pipes are excellent for cold water and ambient temperature applications. However, they are not recommended for continuous flow of hot water exceeding 60°C (140°F). For hot water, CPVC pipes are preferred.', 9, true, '2026-08-11 08:19:47.85', '2026-08-11 08:19:47.85');
INSERT INTO public.faqs VALUES ('cmsoe3mru0009q23j0ee42ycg', 'How do I request a quotation for a large order?', 'You can browse our online catalog, add the products you need to your Enquiry List, and submit it directly through the website. Our sales team will get back to you promptly with a custom quote.', 10, true, '2026-08-11 08:19:47.851', '2026-08-11 08:19:47.851');
INSERT INTO public.faqs VALUES ('cmsoe3mrv000aq23jpxsrug8w', 'Do you offer delivery across Bangladesh?', 'Yes, we have a vast and robust distribution network that allows us to deliver our products to any district or region across Bangladesh safely and on time.', 11, true, '2026-08-11 08:19:47.852', '2026-08-11 08:19:47.852');
INSERT INTO public.faqs VALUES ('cmsoe3mrw000bq23jo8yi6uyj', 'Are uPVC pipes fire-resistant?', 'Yes, uPVC is inherently flame retardant. Unlike regular plastics, uPVC will not support combustion and stops burning once the external flame source is removed.', 12, true, '2026-08-11 08:19:47.853', '2026-08-11 08:19:47.853');
INSERT INTO public.faqs VALUES ('cmsoe3mrx000cq23jb7cnhtt9', 'What is an Auto-Belling machine?', 'Auto-Belling machines are advanced manufacturing equipment we use to automatically form the sockets (bells) at the end of pipes. This ensures perfectly uniform, seamless joints that prevent leaks.', 13, true, '2026-08-11 08:19:47.854', '2026-08-11 08:19:47.854');
INSERT INTO public.faqs VALUES ('cmsoe3mry000dq23j7rmx1a3o', 'How should uPVC pipes be stored before installation?', 'Pipes should be stored on a flat surface, protected from direct prolonged sunlight if stored outdoors for months, and should not be dropped or dragged across rough surfaces.', 14, true, '2026-08-11 08:19:47.854', '2026-08-11 08:19:47.854');
INSERT INTO public.faqs VALUES ('cmsoe3mrz000eq23jur59oj3d', 'Can uPVC pipes be used for underground irrigation?', 'Yes, our pressure pipes and agricultural pipes are highly durable and specifically designed to withstand soil pressure, making them perfect for underground irrigation and deep tube-wells.', 15, true, '2026-08-11 08:19:47.855', '2026-08-11 08:19:47.855');
