INSERT INTO public.pages VALUES ('cmsmvl48w00fiu30l1swdqsp2', 'About Us', 'about', '<h2>About Talukder uPVC Fittings Industries Ltd.</h2><p>Talukder uPVC Fittings Industries Ltd., a concern of Talukder Group of Industries, is one of the leading manufacturers of uPVC pipes and fittings in Bangladesh. With a commitment to quality and innovation, we produce a comprehensive range of uPVC products for water supply, drainage, irrigation, and sanitation applications.</p><p>Our manufacturing facility is equipped with modern machinery including auto-belling machines, ensuring consistent quality across all our products. Every pipe and fitting is manufactured as per BS-3505 standard using 100% virgin material.</p>', NULL, NULL, true, '2026-08-10 06:53:44.768', '2026-08-10 06:53:44.768');
INSERT INTO public.pages VALUES ('cmsmvl49100fju30lesg3q0zv', 'Privacy Policy', 'privacy', '<h2>Privacy Policy</h2><p>Talukder uPVC Fittings Industries Ltd. is committed to protecting your privacy. This policy outlines how we collect, use, and protect your personal information when you use our website.</p><p>We collect personal information only when you voluntarily submit an enquiry or quote request. This information is used solely for the purpose of responding to your enquiry and is not shared with third parties.</p>', NULL, NULL, true, '2026-08-10 06:53:44.774', '2026-08-10 06:53:44.774');
INSERT INTO public.pages VALUES ('cmsmvl49400fku30lmn1w3rba', 'Terms of Use', 'terms', '<h2>Terms of Use</h2><p>By accessing and using the Talukder uPVC website, you agree to these terms of use. The product information, specifications, and images provided on this website are for informational purposes only.</p><p>Product specifications may change without notice. Please confirm all specifications with our sales team before placing an order.</p>', NULL, NULL, true, '2026-08-10 06:53:44.776', '2026-08-10 06:53:44.776');
